-- ==========================================================================
-- Plan de culture maraichere - 013 · Six ans d'assolement releve
-- 2021 a 2026, transcrits des feuilles manuscrites puis verifies au
-- visuel, parcelle par parcelle, avec Coco.
-- ==========================================================================

-- --------------------------------------------------------------------------
-- Rejouable
-- L'editeur SQL de Supabase valide instruction par instruction : une
-- execution interrompue laisse donc derriere elle ce qu'elle avait deja
-- fait. On efface avant de reposer, pour que relancer ce fichier donne
-- toujours le meme resultat.
-- --------------------------------------------------------------------------

drop view  if exists production.v_precedent_cultural;
drop table if exists production.assolement_releve;


-- --------------------------------------------------------------------------
-- Familles botaniques : menage avant d'y accrocher six ans
-- L'import FileMaker a laisse 'ombellifere' et 'ombellifère' cote a cote,
-- et trois familles manquent : labiee, poacee, rosacee.
-- --------------------------------------------------------------------------

update production.legume set famille_botanique_id =
  (select id from production.famille_botanique where code = 'FAM09')
 where famille_botanique_id =
  (select id from production.famille_botanique where code = 'FAM10');
delete from production.famille_botanique where code = 'FAM10';

update production.famille_botanique set nom = 'ombellifère' where code = 'FAM09';
update production.famille_botanique set nom = 'convolvulacées' where code = 'FAM04';
update production.famille_botanique set nom = 'légumineuse' where code = 'FAM08';

insert into production.famille_botanique (id, code, nom) values
  ('79c9fe45-6222-538e-95a2-6e82c43f880f', 'FAM12', 'labiée'),
  ('d5ca3205-ac03-5230-9ffc-939675d594e5', 'FAM13', 'graminée'),
  ('e4859de9-3761-5c45-ada4-84e60b217ca0', 'FAM14', 'rosacée')
on conflict (code) do nothing;


-- --------------------------------------------------------------------------
-- Le releve d'assolement
-- Une ligne par entree de feuille. Les numeros de planche sont convertis
-- dans la convention du 20 octobre 2026 ; ceux de la feuille sont gardes
-- a cote, pour pouvoir revenir au document et relire l'ecriture.
-- --------------------------------------------------------------------------

create table production.assolement_releve (
  id                    uuid primary key default gen_random_uuid(),
  annee                 smallint not null check (annee between 2000 and 2100),
  parcelle_id           uuid not null references production.parcelle (id)
                          on delete cascade,
  rang                  smallint not null check (rang > 0),
  planche_debut         smallint check (planche_debut > 0),
  planche_fin           smallint check (planche_fin > 0),
  nb_planches_ecrit     numeric(6,2) check (nb_planches_ecrit > 0),
  libelle               text not null,
  famille_botanique_id  uuid references production.famille_botanique (id),
  est_engrais_vert      boolean not null default false,
  est_passage           boolean not null default false,
  est_sans_culture      boolean not null default false,
  feuille_nom           text not null,
  feuille_planche_1_au  text not null,
  feuille_nb_planches   smallint,
  feuille_planche_debut smallint,
  feuille_planche_fin   smallint,
  note                  text,
  unique (parcelle_id, annee, rang),
  constraint releve_plage_coherente check (
    (planche_debut is null) = (planche_fin is null)
    and (planche_debut is null or planche_fin >= planche_debut))
);

create index releve_parcelle_idx on production.assolement_releve
  (parcelle_id, annee);
create index releve_famille_idx on production.assolement_releve
  (famille_botanique_id);

comment on column production.assolement_releve.planche_debut is
  'Premiere planche, dans la convention du 20 octobre 2026 : planche 1 au sud ou a l''ouest. Null quand la feuille ne donne pas de plage -- les feuilles LAUCH n''ont pas de planches numerotees.';

comment on column production.assolement_releve.nb_planches_ecrit is
  'Le nombre ecrit a la main a cote de l''accolade. Quand il contredit la plage, c''est lui qui fait foi : l''accolade est posee a vue, le nombre est compte.';

comment on column production.assolement_releve.libelle is
  'Le libelle tel qu''il est ecrit sur la feuille, sans normalisation. C''est la seule chose dont on soit certain.';

comment on column production.assolement_releve.famille_botanique_id is
  'Famille lue dans le libelle. Null pour un engrais vert -- un melange pois, vesce, ble n''a pas une famille mais deux -- et pour un passage.';

comment on column production.assolement_releve.est_sans_culture is
  'La parcelle existait et n''a rien porte cette annee-la. A ne pas confondre avec l''absence de ligne, qui veut dire qu''on n''a pas le document -- et avec hors_rotation sur la parcelle, qui veut dire qu''elle ne suit pas l''assolement du tout.';

comment on column production.assolement_releve.feuille_planche_1_au is
  'Le bout d''ou la feuille numerote. Jusqu''en 2026 il change d''une annee a l''autre sur la meme parcelle : F2 part du nord en 2024, du sud en 2025. C''est ce qui rend la conversion necessaire, et c''est ce qui permet de la refaire si on la juge fausse.';

