-- --------------------------------------------------------------------------
-- Le precedent cultural, planche par planche
-- La question que l'appli posera a chaque fois qu'on pose une culture :
-- qu'est-ce qui est passe sur cette planche, et quand ?
-- La vue descend le releve au niveau de la planche. Une entree de six
-- planches en produit six lignes, ce qui rend la question directe.
-- --------------------------------------------------------------------------

create view production.v_precedent_cultural as
select r.annee,
       u.parcelle_id,
       u.id   as unite_culture_id,
       u.ordre,
       r.famille_botanique_id,
       f.nom  as famille,
       r.libelle,
       r.est_engrais_vert,
       r.est_passage
  from production.assolement_releve r
  join production.unite_culture u
    on u.parcelle_id = r.parcelle_id
   and u.ordre between r.planche_debut and r.planche_fin
  left join production.famille_botanique f
    on f.id = r.famille_botanique_id;

comment on view production.v_precedent_cultural is
  'Le releve d''assolement descendu a la planche. Ne porte que le constate, jamais le prevu : une culture planifiee mais jamais plantee n''y figure pas.';


-- --------------------------------------------------------------------------
-- Droits
-- --------------------------------------------------------------------------

alter table production.assolement_releve enable row level security;
create policy assolement_releve_lecture on production.assolement_releve
  for select to anon, authenticated using (true);
grant select on production.assolement_releve to anon, authenticated;
grant select on production.v_precedent_cultural to anon, authenticated;

create trigger assolement_releve_audit
  after insert or update or delete on production.assolement_releve
  for each row execute function production.tracer_historique();


-- --------------------------------------------------------------------------
-- Controle
-- --------------------------------------------------------------------------

do $$
declare n integer; hors integer;
begin
  select count(*) into n from production.assolement_releve;
  if n <> 521 then
    raise exception 'Releve incomplet : % lignes au lieu de 521', n;
  end if;

  select count(*) into hors
    from production.assolement_releve r
    join production.parcelle p on p.id = r.parcelle_id
   where r.planche_fin is not null
     and r.planche_fin > (select count(*) from production.unite_culture u
                           where u.parcelle_id = p.id);
  if hors > 0 then
    raise exception '% plages de planches sortent de leur parcelle', hors;
  end if;
end $$;

